ShapeCanvas(selection: $selection)
    .focusable()
    .onCopyCommand {
        selection.map { NSItemProvider(object: $0.svgText as NSString) }
    }

DiagramCanvas(selection: $selection)
    .focusable()
    .onDeleteCommand {
        diagram.remove(selection)
        selection.removeAll()
    }

SearchOverlay(query: $query)
    .onExitCommand {
        isSearchPresented = false
    }

GameBoard(board: board)
    .focusable()
    .onMoveCommand { direction in
        switch direction {
        case .left: board.shift(.west)
        case .right: board.shift(.east)
        default: break
        }
    }

PlayerSurface(player: player)
